cypress_script:
describe('Shopping Cart Page', () => {
  it('should display shopping cart items and allow checkout', () => {
    cy.visit('https://www.saucedemo.com/cart.html');
    cy.get('[data-test="primary-header"]').should('be.visible').and('have.text', 'Your Cart');
    cy.get('[data-test="continue-shopping"]').should('be.visible');
    cy.get('[data-test="checkout"]').should('be.visible');
  });

  it('should not navigate away when continue shopping is clicked', () => {
    cy.visit('https://www.saucedemo.com/cart.html');
    cy.get('[data-test="continue-shopping"]').click();
    cy.url().should('eq', 'https://www.saucedemo.com/cart.html');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Shopping Cart Page', () => {
  test('should display shopping cart items and allow checkout', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/cart.html');
    await expect(page.locator('[data-test="primary-header"]')).toBeVisible();
    await expect(page.locator('[data-test="primary-header"]')).toHaveText('Your Cart');
    await expect(page.locator('[data-test="continue-shopping"]')).toBeVisible();
    await expect(page.locator('[data-test="checkout"]')).toBeVisible();
  });

  test('should not navigate away when continue shopping is clicked', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/cart.html');
    await page.click('[data-test="continue-shopping"]');
    await expect(page).toHaveURL('https://www.saucedemo.com/cart.html');
  });
});
